from pysat.solvers import Solver
from pysat.card import CardEnc
from itertools import combinations

n = 8
vertices = list(range(n))
edges = list(combinations(vertices, 2))
edge_to_idx = {e: i for i, e in enumerate(edges)}
idx_to_edge = {i: e for i, e in enumerate(edges)}
num_edges = len(edges)

# Use Solver (e.g., Glucose3)
solver = Solver(name='glucose3')

# Create variables for edges (1-indexed)
edge_vars = {}
for i, e in enumerate(edges):
    v = i + 1
    edge_vars[e] = v

# Fixed edges
solver.add_clause([edge_vars[(0,7)]])
solver.add_clause([edge_vars[(1,7)]])

# Degree constraints: for each vertex, sum of incident edges between 3 and 4.
for v in vertices:
    incident = [edge_vars[(min(v,u), max(v,u))] for u in vertices if u != v]
    # at least 3
    c_atleast = CardEnc.atleast(lits=incident, bound=3, topk=num_edges, encoding='totalizer')
    for cl in c_atleast:
        solver.add_clause(cl)
    # at most 4
    c_atmost = CardEnc.atmost(lits=incident, bound=4, topk=num_edges, encoding='totalizer')
    for cl in c_atmost:
        solver.add_clause(cl)

# Total edges between 13 and 16
all_edge_vars = [edge_vars[e] for e in edges]
c_total_atleast = CardEnc.atleast(lits=all_edge_vars, bound=13, topk=num_edges, encoding='totalizer')
for cl in c_total_atleast:
    solver.add_clause(cl)
c_total_atmost = CardEnc.atmost(lits=all_edge_vars, bound=16, topk=num_edges, encoding='totalizer')
for cl in c_total_atmost:
    solver.add_clause(cl)

# Now 3-colorability
next_var = num_edges + 1

color_vars = {}
for v in vertices:
    for c in range(3):
        color_vars[(v,c)] = next_var
        next_var += 1

# Each vertex exactly one color
for v in vertices:
    solver.add_clause([color_vars[(v,0)], color_vars[(v,1)], color_vars[(v,2)]])
    for c1 in range(3):
        for c2 in range(c1+1, 3):
            solver.add_clause([-color_vars[(v,c1)], -color_vars[(v,c2)]])

# Edge constraints: if edge present, endpoints different colors
for e in edges:
    u,v = e
    ev = edge_vars[e]
    for c in range(3):
        solver.add_clause([-ev, -color_vars[(u,c)], -color_vars[(v,c)]])

# Solve
status = solver.solve()
print("Satisfiable:", status)
if status:
    model = solver.get_model()
    true_vars = set([abs(l) for l in model if l > 0])
    present_edges = []
    for e in edges:
        if edge_vars[e] in true_vars:
            present_edges.append(e)
    print("Edges:", present_edges)
    print("Number of edges:", len(present_edges))
    deg = {v:0 for v in vertices}
    for u,v in present_edges:
        deg[u] += 1
        deg[v] += 1
    print("Degrees:", deg)
    coloring = {}
    for v in vertices:
        for c in range(3):
            if color_vars[(v,c)] in true_vars:
                coloring[v] = c
    print("Coloring:", coloring)
else:
    print("Unsatisfiable")
